<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title><?= $esc($title); ?></title><link href="<?= base_url(); ?>assets/css/bootstrap.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/icons.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/app.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/dashboard-unified.css" rel="stylesheet"><style>body{background:#f4f8fc}.donation-shell{padding:30px 0}.donation-hero{padding:28px;border-radius:20px;color:#fff;background:linear-gradient(135deg,#272b8c,#3c40c6);box-shadow:0 18px 40px rgba(39,43,140,.16)}.donation-hero h1{margin:8px 0;color:#fff;font-size:2rem;font-weight:700}.donation-hero p{margin:0;color:rgba(255,255,255,.82)}.donation-card{margin-top:24px;border:0;border-radius:18px;box-shadow:0 16px 38px rgba(15,23,42,.08);overflow:hidden}.donation-card .table th{border-top:0;color:#68708a;font-size:.72rem;letter-spacing:.06em;text-transform:uppercase;white-space:nowrap}.donation-card .table td{vertical-align:middle}.school-address{display:block;margin-top:4px;color:#6c757d;font-size:.8rem}.empty{padding:42px;text-align:center;color:#6c757d}</style></head><body class="dashboard-root-theme"><div id="wrapper"><?php include(__DIR__ . '/../includes/top-bar.php'); ?><?php include(__DIR__ . '/../includes/sidebar.php'); ?><div class="content-page"><div class="content"><main class="container-fluid dashboard-shell donation-shell"><section class="donation-hero"><a class="btn btn-sm btn-light" href="<?= base_url(); ?>Brigada/list_of_partners">← Back to Partners</a><h1>Donation Details</h1><p><?= $esc($partner->name ?? 'Partner'); ?> — recorded Brigada Eskwela support.</p></section><section class="card donation-card"><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Date</th><th>Recipient School</th><th>Contribution</th><th>Type</th><th>Qty</th><th>Unit</th><th>Amount</th><th>Status</th><th>Remarks</th></tr></thead><tbody><?php foreach((array) $donations as $donation): ?><?php $address = $schoolAddress($donation); ?><tr><td><?= $esc($donation->c_date ?? ''); ?></td><td><strong><?= $esc($donation->schoolName ?? '—'); ?></strong><?php if($address !== ''): ?><span class="school-address"><?= $esc($address); ?></span><?php endif; ?></td><td><?= $esc($donation->project_name ?? $donation->spicific_contribution ?? '—'); ?></td><td><?= $esc($donation->contribution_type ?? '—'); ?></td><td><?= $esc($donation->quantity_of_conftribution ?? '—'); ?></td><td><?= $esc($donation->unit_of_contribution ?? '—'); ?></td><td><?= !empty($donation->amount) ? '₱' . number_format((float) $donation->amount, 2) : '—'; ?></td><td><?= $esc($donation->status_agreement ?? '—'); ?></td><td><?= $esc($donation->remarks ?? '—'); ?></td></tr><?php endforeach; ?><?php if(empty($donations)): ?><tr><td colspan="9" class="empty">No donation records found for this partner.</td></tr><?php endif; ?></tbody></table></div></div></section></main></div><?php include(__DIR__ . '/../includes/footer.php'); ?></div></div><script src="<?= base_url(); ?>assets/js/vendor.min.js"></script><script src="<?= base_url(); ?>assets/js/app.min.js"></script></body></html>
